<?php require_once "../includes/config.php"; checkAuth(); if($_SERVER["REQUEST_METHOD"]==="POST"&&isset($_POST["save"])){foreach($_POST as $k=>$v){if($k!=="save"&&$k!=="csrf"){$pdo->prepare("INSERT INTO sys_settings(setting_key,setting_value,setting_group)VALUES(?,?,?)ON DUPLICATE KEY UPDATE setting_value=?")->execute([$k,$v,"general",$v]);}}$success="✅ تم حفظ الإعدادات";}$settings=$pdo->query("SELECT * FROM sys_settings ORDER BY setting_group,setting_key")->fetchAll(); ?>
